return function(c) local n=0 local i=1 while i<=8 do if c.history[i]==nil then break end n=i i=i+1 end local st=c.state if st<0 or st>1000000 then st=0 end local nst=st+1 if nst>1000000 then nst=0 end if n==0 then return {dx=0,dy=0,state=nst} end local echo=c.history[1] local newest=c.history[n] local px=newest.x-c.mx local py=newest.y-c.my local apx=px if apx<0 then apx=-apx end local apy=py if apy<0 then apy=-apy end local od=apx if apy>od then od=apy end if od<3 then local dx=0 local dy=0 if px>0 then dx=-1 elseif px<0 then dx=1 end if py>0 then dy=-1 elseif py<0 then dy=1 end if dx==0 and dy==0 then dx=1 end return {dx=dx,dy=dy,state=nst} end local phase=st%4 if phase==0 then return {dx=0,dy=0,state=nst} end local dx=0 local dy=0 local back=false if n>=3 then local ax=c.history[n-1].x-c.history[n-2].x local ay=c.history[n-1].y-c.history[n-2].y local bx=newest.x-c.history[n-1].x local by=newest.y-c.history[n-1].y if ax>1 then ax=1 elseif ax<-1 then ax=-1 end if ay>1 then ay=1 elseif ay<-1 then ay=-1 end if bx>1 then bx=1 elseif bx<-1 then bx=-1 end if by>1 then by=1 elseif by<-1 then by=-1 end if (bx~=0 or by~=0) and (ax~=bx or ay~=by) then back=true dx=ax dy=ay end end if not back then local tx=echo.x-c.mx local ty=echo.y-c.my if phase==1 then if tx>0 then dx=1 elseif tx<0 then dx=-1 end if dx==0 then if ty>0 then dy=1 elseif ty<0 then dy=-1 end end else if ty>0 then dy=1 elseif ty<0 then dy=-1 end if dy==0 then if tx>0 then dx=1 elseif tx<0 then dx=-1 end end end end if dx==0 and dy==0 then return {dx=0,dy=0,state=nst} end local nx=c.mx+dx-newest.x local ny=c.my+dy-newest.y if nx<0 then nx=-nx end if ny<0 then ny=-ny end local nd=nx if ny>nd then nd=ny end if nd<3 then dx=0 dy=0 if px>0 then dx=-1 elseif px<0 then dx=1 end if py>0 then dy=-1 elseif py<0 then dy=1 end if dx==0 and dy==0 then dx=1 end end if dx>1 then dx=1 elseif dx<-1 then dx=-1 end if dy>1 then dy=1 elseif dy<-1 then dy=-1 end return {dx=dx,dy=dy,state=nst} end